import{_ as a,o as e,c as i,ai as t}from"./chunks/framework.Ci0kozOl.js";const u=JSON.parse('{"title":"Queue Management","description":"","frontmatter":{},"headers":[],"relativePath":"2.0/advanced/queue-management.md","filePath":"2.0/advanced/queue-management.md","lastUpdated":1778854311000}'),n={name:"2.0/advanced/queue-management.md"};function l(o,s,h,p,r,d){return e(),i("div",null,[...s[0]||(s[0]=[t(`<h1 id="queue-management" tabindex="-1">Queue Management <a class="header-anchor" href="#queue-management" aria-label="Permalink to &quot;Queue Management&quot;">​</a></h1><p>This guide explains how to manage import/export jobs using terminal commands and cron scheduling.</p><h2 id="running-jobs-via-terminal" tabindex="-1">Running Jobs via Terminal <a class="header-anchor" href="#running-jobs-via-terminal" aria-label="Permalink to &quot;Running Jobs via Terminal&quot;">​</a></h2><h3 id="processing-single-jobs" tabindex="-1">Processing Single Jobs <a class="header-anchor" href="#processing-single-jobs" aria-label="Permalink to &quot;Processing Single Jobs&quot;">​</a></h3><p>To run a specific import or export job:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Format: php artisan unopim:queue:work &lt;job_id&gt; &lt;user_email&gt; [options]</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">php</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> artisan</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> unopim:queue:work</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 1</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> admin@example.com</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># With additional options</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">php</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> artisan</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> unopim:queue:work</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 1</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> admin@example.com</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --queue=custom-queue</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --timeout=120</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --tries=3</span></span></code></pre></div><p>Required parameters:</p><ul><li><code>job_id</code>: ID of the import/export job (required)</li><li><code>user_email</code>: The email of the unopim user executing the job (required)</li></ul><p>Optional parameters:</p><ul><li><code>--queue</code>: Specify custom queue name</li><li><code>--name</code>: Worker name (default: &#39;single&#39;)</li><li><code>--memory</code>: Memory limit in MB (default: 128)</li><li><code>--timeout</code>: Job timeout in seconds (default: 60)</li><li><code>--tries</code>: Number of retry attempts (default: 1)</li></ul><div class="warning custom-block"><p class="custom-block-title">Important</p><p>Both <code>job_id</code> and <code>user_email</code> are required parameters. The command will fail if either is missing or invalid.</p></div><h3 id="managing-queue-workers" tabindex="-1">Managing Queue Workers <a class="header-anchor" href="#managing-queue-workers" aria-label="Permalink to &quot;Managing Queue Workers&quot;">​</a></h3><p>Basic queue management commands:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Start the queue worker</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">php</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> artisan</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> queue:work</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --queue=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;system,completeness,default&quot;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Restart queue workers (after code changes)</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">php</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> artisan</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> queue:restart</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Stop running queue workers</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">php</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> artisan</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> queue:stop</span></span></code></pre></div><h2 id="scheduling-jobs-with-cron" tabindex="-1">Scheduling Jobs with Cron <a class="header-anchor" href="#scheduling-jobs-with-cron" aria-label="Permalink to &quot;Scheduling Jobs with Cron&quot;">​</a></h2><h3 id="basic-setup" tabindex="-1">Basic Setup <a class="header-anchor" href="#basic-setup" aria-label="Permalink to &quot;Basic Setup&quot;">​</a></h3><ol><li>Configure your crontab:</li></ol><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">crontab</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -e</span></span></code></pre></div><ol start="2"><li>Add the UnoPim scheduler:</li></ol><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">*</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> *</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> *</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> *</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> *</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> cd /path/to/unopim &amp;&amp; </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">php</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> artisan</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> schedule:run</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &gt;&gt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /var/log/unopim/scheduler.log</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> 2&gt;&amp;1</span></span></code></pre></div><h3 id="scheduling-a-single-job" tabindex="-1">Scheduling a Single Job <a class="header-anchor" href="#scheduling-a-single-job" aria-label="Permalink to &quot;Scheduling a Single Job&quot;">​</a></h3><p>To schedule a specific import/export job, add a cron entry that runs the <code>unopim:queue:work</code> command directly:</p><ul><li>Assuming the job ID is 1 and the user email is <a href="mailto:admin@example.com" target="_blank" rel="noreferrer">admin@example.com</a> (replace with your values), schedule it to run every hour.</li></ul><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">0</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> *</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> *</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> *</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> *</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /path/to/unopim</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> &amp;&amp; </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">php</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> artisan</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> unopim:queue:work</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 1</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> admin@example.com</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &gt;&gt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /var/log/unopim/job-1.log</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> 2&gt;&amp;1</span></span></code></pre></div><div class="warning custom-block"><p class="custom-block-title">Important Notes</p><ol><li>Always provide valid job ID and user email</li><li>User must exist in the system</li><li>Queue workers cache code, restart after changes:</li></ol><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">php</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> artisan</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> queue:restart</span></span></code></pre></div></div><h2 id="completeness-queue" tabindex="-1">Completeness Queue <a class="header-anchor" href="#completeness-queue" aria-label="Permalink to &quot;Completeness Queue&quot;">​</a></h2><p>New in v2.0.0, product completeness calculations are processed through a dedicated <strong><code>completeness</code></strong> queue. This ensures that completeness score recalculations do not block default or system queue workers, especially during bulk product updates.</p><p>When starting your queue worker, include the <code>completeness</code> queue alongside the default queues:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">php</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> artisan</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> queue:work</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --queue=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;system,completeness,default&quot;</span></span></code></pre></div><p>If you are using Supervisor, update your configuration to include the <code>completeness</code> queue in the <code>--queue</code> argument (see <a href="./../introduction/configuring_supervisor.html">Configuring Supervisor</a>).</p><h3 id="completeness-recalculation-commands" tabindex="-1">Completeness Recalculation Commands <a class="header-anchor" href="#completeness-recalculation-commands" aria-label="Permalink to &quot;Completeness Recalculation Commands&quot;">​</a></h3><p>You can manually trigger completeness recalculation using the following commands:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Recalculate completeness for all products</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">php</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> artisan</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> unopim:completeness:recalculate</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --all</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Recalculate completeness for a specific attribute family</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">php</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> artisan</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> unopim:completeness:recalculate</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --family=ID</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Recalculate completeness for a single product</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">php</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> artisan</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> unopim:completeness:recalculate</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --product=ID</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Recalculate completeness for specific product IDs</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">php</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> artisan</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> unopim:completeness:recalculate</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --products=1</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --products=2</span></span></code></pre></div><table tabindex="0"><thead><tr><th>Option</th><th>Description</th></tr></thead><tbody><tr><td><code>--all</code></td><td>Recalculate completeness for all products</td></tr><tr><td><code>--family=ID</code></td><td>Recalculate for all products in a specific attribute family</td></tr><tr><td><code>--product=ID</code></td><td>Recalculate for a single product by ID</td></tr><tr><td><code>--products=ID</code></td><td>Recalculate for multiple specific product IDs (repeat the option for each ID)</td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>The <code>--all</code> option dispatches completeness jobs to the <code>completeness</code> queue, so ensure your queue worker is running with the <code>completeness</code> queue included.</p></div><h2 id="dashboard-cache" tabindex="-1">Dashboard Cache <a class="header-anchor" href="#dashboard-cache" aria-label="Permalink to &quot;Dashboard Cache&quot;">​</a></h2><p>To clear the dashboard statistics cache so the next page load shows fresh data, run:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">php</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> artisan</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> unopim:dashboard:refresh</span></span></code></pre></div><p>This is useful when dashboard statistics appear stale or after bulk data operations.</p><hr><h2 id="scheduled-tasks-automatic-via-cron" tabindex="-1">Scheduled Tasks (Automatic via Cron) <a class="header-anchor" href="#scheduled-tasks-automatic-via-cron" aria-label="Permalink to &quot;Scheduled Tasks (Automatic via Cron)&quot;">​</a></h2><p>When the Laravel scheduler is configured (see <a href="#scheduling-jobs-with-cron">Scheduling Jobs with Cron</a>), the following tasks run automatically:</p><table tabindex="0"><thead><tr><th>Task</th><th>Schedule</th><th>Description</th></tr></thead><tbody><tr><td><code>unopim:product:index</code></td><td>Daily at 00:01 &amp; 12:01</td><td>Elasticsearch product re-indexing</td></tr><tr><td><code>unopim:category:index</code></td><td>Daily at 00:01 &amp; 12:01</td><td>Elasticsearch category re-indexing</td></tr><tr><td><code>unopim:completeness:recalculate --all</code></td><td>Daily at 02:00</td><td>Recalculate product completeness scores</td></tr><tr><td><code>unopim:dashboard:refresh</code></td><td>Every 10 minutes</td><td>Refresh dashboard statistics cache</td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>These tasks require the cron entry for <code>php artisan schedule:run</code> to be active. See <a href="#basic-setup">Basic Setup</a> above.</p></div><hr><h2 id="notifications" tabindex="-1">Notifications <a class="header-anchor" href="#notifications" aria-label="Permalink to &quot;Notifications&quot;">​</a></h2><h3 id="completeness-notifications" tabindex="-1">Completeness Notifications <a class="header-anchor" href="#completeness-notifications" aria-label="Permalink to &quot;Completeness Notifications&quot;">​</a></h3><p>When a bulk completeness calculation finishes, all admin users with full permissions are notified via:</p><ol><li><strong>UI notification</strong> — appears in the notification bell in the admin panel.</li><li><strong>Email notification</strong> — sent if SMTP mail is configured in your <code>.env</code> file.</li></ol><h3 id="environment-variables" tabindex="-1">Environment Variables <a class="header-anchor" href="#environment-variables" aria-label="Permalink to &quot;Environment Variables&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Variable</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>NOTIFICATIONS_ENABLED</code></td><td><code>true</code></td><td>Enable or disable all notifications</td></tr><tr><td><code>COMPLETENESS_QUEUE</code></td><td><code>system</code></td><td>Queue name for completeness jobs</td></tr></tbody></table><hr><h2 id="pause-resume-and-cancel-controls" tabindex="-1">Pause, Resume, and Cancel Controls <a class="header-anchor" href="#pause-resume-and-cancel-controls" aria-label="Permalink to &quot;Pause, Resume, and Cancel Controls&quot;">​</a></h2><p>Import and export jobs in v2.0.0 support <strong>pause</strong>, <strong>resume</strong>, and <strong>cancel</strong> controls. These controls are available both in the admin UI and through the job management commands, allowing administrators to:</p><ul><li><strong>Pause</strong> a running import or export job to temporarily halt processing without losing progress.</li><li><strong>Resume</strong> a paused job to continue from where it left off.</li><li><strong>Cancel</strong> a job to stop it entirely and release queue resources.</li></ul>`,55)])])}const k=a(n,[["render",l]]);export{u as __pageData,k as default};
